    'agent.prompt_builder.drugoy_agent_bez_imeni' => '另一个未命名的智能体',
    'agent.prompt_builder.instance_a2a' => '智能体网络（A2A）已开启。我供其他智能体使用的地址：%1$s；卡片：%1$s/.well-known/agent-card.json；入口：%2$s。其他 Mercurius 智能体如何连接我：1) 本服务器的所有者把入口 token 交给那个智能体的所有者：它就是本服务器 .env 文件中的 A2A_TOKEN（我不知道它，也绝不显示）；2) 对方所有者把该 token 作为机密保存（/secret），并运行 /peer add <名称> %1$s <机密名称>，然后 /peer open <名称>；3) 在这里，我的所有者会收到一张“有智能体在敲门”的卡片，上面有其密钥指纹，并由所有者选择它的权限（或者事先执行：/peer allow <名称> <指纹> user）。反过来（我去连接邻居）则是在我这边用 /peer add 填入对方的地址和 token。列表、我的密钥和连接：/peers；我用 peer_delegate 给邻居派任务。',
