    'tool.browser.more_actions' => 'select (ref, value) — 按值或文本选择列表中的选项（选项显示在元素的花括号中，* 表示已选项）；scroll (direction: down, up, top, bottom) — 滚动，页面会加载下方内容；back — 返回历史记录上一页。alert/confirm/prompt 对话框不会阻塞页面：它们会被立即关闭，其文本会随回答一并返回。打开新标签页的链接会使其成为当前标签页。reset（kind：cache —— 缓存，登录保留；profile —— 整个配置文件及登录，需卡片确认）—— 当被要求清除缓存或重置浏览器时使用；配置文件位于浏览器服务中，不在沙箱里。 ',
