    'tool.browser.read_tekst_stranitsy_i_pronumerovannye' => 'read — 页面文本和带编号的元素；click (ref — 元素编号) — 点击；type (ref, text, submit) — 输入 ',
    'tool.browser.script_about' => 'script (path, site, args) — 在已用 open 打开的站点 site 页面上运行沙盒中你自己的 JS 脚本：文件 browser-scripts/read/<site>/<name>.js 读取页面副本（不含脚本的 DOM，无网络：没有 fetch、WebSocket 和定时器；无需批准），browser-scripts/act/<site>/<name>.js 在实时页面上执行操作（等待所有者批准；永久授权仅针对该脚本文本，改动后会再次询问）。脚本是 async 函数的函数体：它接收 args，并通过 return 以 JSON 返回数据。对于站点上重复出现的操作（消息列表、搜索、发送），请先写一次脚本（write_file），之后直接使用它，而不是读取页面再点击。 ',
