    'tool.mcp_manage.about' => '已安装的 MCP：list — 带版本的列表；update — 在当前版本旁安装新版本（相同步骤、试运行；工具集相同则立即切换，不同则等待 mcp_install approve）；rollback — 回到旧版本；rebuild — 按相同步骤重新构建当前版本的依赖（例如出现 NODE_MODULE_VERSION 错误后 —— 模块是为另一个 Node 版本构建的）；remove — 删除安装的代码（不是 .mcp.json 的条目）；remove_entry — 从某上下文的 .mcp.json 中移除条目（name，context：mine、member:<编号>、project:<编号>；不填 context — 本聊天的文件），安装保留；allow / disallow — 允许或撤销某上下文使用该 MCP（context：member:<编号>、project:<编号>、owners）。',
    'tool.mcp_manage.no_right' => '只有拥有 mcp 权限的参与者才能管理 MCP。',
    'tool.mcp_install.about' => "将 MCP 服务器安装到沙箱（拥有 mcp 权限的参与者）。fetch — 获取源码：url — git 仓库的 https 地址，或 path — 沙箱中的 .tar.gz/.zip 压缩包；回复中包含 README 和依赖文件 — 阅读后制定计划。install — 执行计划：steps（以独立的 MCP 用户在版本目录中执行的命令，不含密钥，例如 npm ci、npm run build）和 entry — .mcp.json 条目（command；args 中通过 \${INSTALL_DIR} 指向代码路径；env 中为密钥名 {NAME}）；随后试运行并列出工具。approve — 批准所示工具集：classes=hints（危险类别按服务器标注）或 irreversible（全部不可逆）；之后条目会出现在此上下文的 .mcp.json 中。仓库中现成的 mercurius.mcp.json 即为现成计划。",
