    'tool.http_request.podderzhivayutsya_tolko_adresa_http_i' => '仅支持 http 和 https 地址。',
    'tool.http_request.secret_about' => '保险库中机密的名称（/secret），用于请求头：代码会填入其值，你永远看不到。机密也可以通过标记 {{secret:name}} 放入正文或请求头的值中 — 例如登录表单 username={{secret:panel-user}}&password={{secret:panel-pass}}，Content-Type 为 application/x-www-form-urlencoded（值会根据 Content-Type 按表单或 JSON 编码）；网站要求在地址中传密码时，也可放入地址的查询部分：url http://site/?password={{secret:site-pass}}（只能在“?”之后，不能在主机名中）。带机密的请求会经过所有者的卡片确认；“始终允许”针对的是机密集合和主机。服务器下发的 Cookie（登录后的会话）由代码自行为项目或参与者保存，并随之后对同一主机的请求发送；你永远看不到它们。页面的表单令牌（<meta name="csrf-token">）由代码自行保存，并在同一主机的下一次更改请求中作为 X-CSRF-Token 请求头添加 — 不要复制它；任何长值都要完整复制，切勿用“…”缩短。',
    'tool.http_request.secret_header_about' => '机密所用的请求头；默认为 Authorization: Bearer <secret>，其他请求头则取原始值（例如 X-Api-Key）。',
    'tool.http_request.secret_https_only' => '机密只通过 https 发送。',
    'tool.http_request.secret_in_host' => '机密只能放入地址的查询部分（“?”之后）、正文或请求头——不能放入主机名或路径：主机必须是授权所绑定的那个。',
    'tool.http_request.secret_redirect_stopped' => '服务器将请求重定向到 %s — 机密没有发送到那里，重定向也未被跟随。如果需要该地址，请单独向它发起请求：所有者将收到针对新主机的卡片。',
    'tool.http_request.slishkom_mnogo_perenapravleniy_bolshe' => '重定向次数过多（超过 %d 次）。',
